inbound.set-body:
@{
      var body = context.Request.Body.As(preserveContent: true);
      body["warehouse_id"] = "{{databricks-warehouse-id}}";
      if (body["wait_timeout"] == null) { body["wait_timeout"] = "50s"; }
      body["on_wait_timeout"] = "CONTINUE";
      body["format"] = "JSON_ARRAY";
      body["disposition"] = "INLINE";
      return body.ToString();
    }
